));

CREATE POLICY "Owners can update their venue policies"
ON public.venue_policies FOR UPDATE
USING (EXISTS (
  SELECT 1 FROM venues WHERE venues.id = venue_policies.venue_id AND venues.owner_id = auth.uid()
));

